const int trigPin = 9;
const int echoPin = 10;
const int ledPin = 11;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  long duration, distance;
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  duration = pulseIn(echoPin, HIGH);
  distance = (duration / 2) / 29.1;

  if (distance < 100) {
    digitalWrite(ledPin, HIGH);
    delay(1000 - distance);
    digitalWrite(ledPin, LOW);
    delay(1000 - distance);
  } else {
    digitalWrite(ledPin, HIGH);
    delay(100);
    digitalWrite(ledPin, LOW);
    delay(100);
  }
}
```
This code will adjust the speed of the blinking LED based on the distance read from the ultrasonic sensor. The closer the object, the faster the LED will blink.
